    # the bottom boundary grows upward only along its own two columns.
    for c in range(w-1):
        if grid[0][c] != bg and grid[0][c+1] == grid[0][c]:
            for r in range(1, h):
                for x in (c,c+1):
                    if grid[r][x] == bg: out[r][x] = 7
        if grid[h-1][c] != bg and grid[h-1][c+1] == grid[h-1][c]:
            for r in range(h-2, -1, -1):
